import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import type { DisposablesManager } from 'kea-disposables'
import posthog from 'posthog-js'

import { playUiSound, warmUpUiSound } from './playUiSound'
import { uiSoundForTarget } from './uiSoundForTarget'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface uiSoundsLogicValues {
    uiSoundsEnabled: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface uiSoundsLogicActions {
    setUiSoundsEnabled: (enabled: boolean) => {
        enabled: boolean
    }
}

export type uiSoundsLogicType = MakeLogicType<uiSoundsLogicValues, uiSoundsLogicActions>

const POINTER_LISTENER_KEY = 'uiSoundsPointerListener'

function handlePointerDown(event: PointerEvent): void {
    if (event.button !== 0 || event.isPrimary === false) {
        return
    }
    const sound = uiSoundForTarget(event.target)
    if (sound) {
        playUiSound(sound)
    }
}

function handlePointerOver(event: PointerEvent): void {
    const sound = uiSoundForTarget(event.target)
    if (sound) {
        warmUpUiSound(sound)
    }
}

function listenForPresses(disposables: DisposablesManager, enabled: boolean): void {
    if (!enabled) {
        disposables.dispose(POINTER_LISTENER_KEY)
        return
    }
    disposables.add(() => {
        // Capture runs before the component toggles its state, and before any stopPropagation can hide the press.
        document.addEventListener('pointerdown', handlePointerDown, true)
        document.addEventListener('pointerover', handlePointerOver, true)
        return () => {
            document.removeEventListener('pointerdown', handlePointerDown, true)
            document.removeEventListener('pointerover', handlePointerOver, true)
        }
    }, POINTER_LISTENER_KEY)
}

export const uiSoundsLogic = kea<uiSoundsLogicType>([
    // pinned: the path and reducer name form the localStorage key. Renaming either turns sounds off for everyone.
    path(['lib', 'uiSounds', 'uiSoundsLogic']),
    actions({
        setUiSoundsEnabled: (enabled: boolean) => ({ enabled }),
    }),
    reducers({
        uiSoundsEnabled: [false, { persist: true }, { setUiSoundsEnabled: (_, { enabled }) => enabled }],
    }),
    listeners(({ cache }) => ({
        setUiSoundsEnabled: ({ enabled }) => {
            listenForPresses(cache.disposables, enabled)
            // pinned: analytics event name and property. Renaming them breaks dashboards.
            posthog.capture('ui sounds toggled', { enabled })
        },
    })),
    afterMount(({ values, cache }) => {
        listenForPresses(cache.disposables, values.uiSoundsEnabled)
    }),
])
